import React from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { 
  Home, 
  MapPin, 
  User, 
  MessageSquare, 
  Info, 
  Heart,
  Package,
  Building2
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

const Sidebar = () => {
  const location = useLocation();
  const { user } = useAuth();

  const menuItems = [
    { path: '/', icon: Home, label: 'HOME' },
    { path: '/orphanages', icon: Building2, label: 'LOCATION' },
    { path: '/profile', icon: User, label: 'PROFILE' },
    { path: '/donations', icon: Package, label: 'DONATIONS' },
    { path: '/donate', icon: Heart, label: 'DONATE' },
    { path: '/feedback', icon: MessageSquare, label: 'FEEDBACK' },
    { path: '/about', icon: Info, label: 'ABOUT US' },
  ];

  return (
    <div className="w-64 bg-white shadow-lg border-r border-secondary-200 flex flex-col">
      {/* Logo */}
      <div className="p-6 border-b border-secondary-200">
        <h1 className="text-2xl font-cursive font-bold text-gradient">
          NurtureNest.
        </h1>
      </div>

      {/* Navigation Menu */}
      <nav className="flex-1 p-4 space-y-2">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = location.pathname === item.path;

          return (
            <NavLink
              key={item.path}
              to={item.path}
              className={`sidebar-item ${isActive ? 'active' : ''}`}
            >
              <Icon className="w-5 h-5 mr-3" />
              <span className="font-medium">{item.label}</span>
            </NavLink>
          );
        })}
      </nav>

      {/* User Info */}
      <div className="p-4 border-t border-secondary-200">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-primary-100 rounded-full flex items-center justify-center">
            <User className="w-5 h-5 text-primary-600" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-secondary-900 truncate">
              {user?.name || 'User'}
            </p>
            <p className="text-xs text-secondary-500 capitalize">
              {user?.role || 'donor'}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
